double ft = 0.3048;
double dz = Tama.Args.Get(args, "deltaMm", 300.0) / 304.8;
Func<double,double> wrap = x => Math.Atan2(Math.Sin(x), Math.Cos(x));
var sp = new FilteredElementCollector(doc).OfClass(typeof(BasePoint)).Cast<BasePoint>().First(b => b.IsShared);
var spBefore = sp.SharedPosition;
var act = doc.ActiveProjectLocation;
var locs = new List<ProjectLocation>(); foreach (ProjectLocation pl in doc.ProjectLocations) locs.Add(pl);
var before = locs.ToDictionary(l => l.Id.IntegerValue, l => l.GetProjectPosition(XYZ.Zero));
// active first, then others
foreach (var l in locs.OrderBy(x => x.Id == act.Id ? 0 : 1))
{
    var b = before[l.Id.IntegerValue];
    var pp = l.GetProjectPosition(XYZ.Zero);
    pp.EastWest = b.EastWest; pp.NorthSouth = b.NorthSouth; pp.Angle = b.Angle; pp.Elevation = b.Elevation + dz;
    l.SetProjectPosition(XYZ.Zero, pp);
    doc.Regenerate();
    var r = l.GetProjectPosition(XYZ.Zero);
    if (Math.Abs(wrap(r.Angle - b.Angle)) > 1e-9)
    {   // mirrored site: angle reflects on write (read_new = 2*read_old - set)
        var p2 = l.GetProjectPosition(XYZ.Zero);
        p2.Angle = wrap(2 * r.Angle - b.Angle);
        l.SetProjectPosition(XYZ.Zero, p2);
        doc.Regenerate();
    }
}
var outList = new List<object>();
foreach (var l in locs)
{
    var b = before[l.Id.IntegerValue]; var r = l.GetProjectPosition(XYZ.Zero);
    double dEN = Math.Sqrt(Math.Pow(r.EastWest-b.EastWest,2)+Math.Pow(r.NorthSouth-b.NorthSouth,2))*ft*1000;
    double dZ = (r.Elevation - b.Elevation)*ft*1000;
    double dA = Math.Abs(wrap(r.Angle-b.Angle))*180/Math.PI;
    if (dEN > 0.5 || Math.Abs(dZ - dz*304.8) > 0.5 || dA > 1e-6) throw new Exception(l.Name + " check failed (EN " + dEN + " mm, dZ " + dZ + " mm, angle " + dA + " deg) - rolled back.");
    outList.Add(new { site = l.Name, current = l.Id == act.Id, elevBefore = Math.Round(b.Elevation*ft,4), elevAfter = Math.Round(r.Elevation*ft,4),
        ew = Math.Round(r.EastWest*ft,4), ns = Math.Round(r.NorthSouth*ft,4), angle = Math.Round(r.Angle*180/Math.PI,6) });
}
var spa = sp.SharedPosition;
if (Math.Sqrt(Math.Pow(spa.X-spBefore.X,2)+Math.Pow(spa.Y-spBefore.Y,2))*ft > 0.001) throw new Exception("Survey point E/N changed - rolled back.");
return new { sites = outList, surveyReads_m = new[]{Math.Round(spa.X*ft,4), Math.Round(spa.Y*ft,4), Math.Round(spa.Z*ft,4)}, surveyInternal_m = new[]{Math.Round(sp.Position.X*ft,4), Math.Round(sp.Position.Y*ft,4), Math.Round(sp.Position.Z*ft,4)} };
